// Tensor-core FlashAttention forward (sm_86): wmma m16n16k16 bf16, 4 warps,
// BLOCK_M=64 query rows, BLOCK_N=64 keys per tile, online softmax in the
// exp2 domain, GQA support. BF16 in/out, FP32 accumulation.
//
// Warp w owns query rows [16w, 16w+16). Q lives in registers as 8 wmma A
// fragments (16x16x16 row-major, ldm 128). K/V tiles are staged in shared
// memory. Per K/V tile a warp does 4 QK mma -> 4 S accumulators (16 rows x
// 64 cols, 8 floats/lane), then per-lane online softmax (each lane owns rows
// {gid, gid+8} x cols {2*tig, 2*tig+1, 2*tig+8, 2*tig+9} in every 16-col
// group), then 32 PV mma accumulate O (8 head-dim-half accumulators). The P
// fragment is assembled in place from the softmaxed S accumulator, whose
// layout matches the m16n16k16 matrix_a layout, so no shuffles are needed.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <math.h>

namespace {

constexpr int BLOCK_M = 64;
constexpr int BLOCK_N = 64;
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr float LOG2E = 1.4426950408889634f;
constexpr float NEG_INF = -INFINITY;

using namespace nvcuda;

__global__ void __launch_bounds__(NUM_THREADS, 2) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, float scale_log2, bool causal, int q_per_kv)
{
    __shared__ __nv_bfloat16 sK[BLOCK_N][HEAD_DIM];
    __shared__ __nv_bfloat16 sV[BLOCK_N][HEAD_DIM];

    const int m_tile = blockIdx.x;
    const int bh = blockIdx.y;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int gid = lane / 4, tig = lane % 4;

    const long long base = (long long)bh * seq_len * HEAD_DIM;
    const long long base_kv = (long long)(bh / q_per_kv) * seq_len * HEAD_DIM;
    const int grow0 = m_tile * BLOCK_M + warp * 16;

    // ---- Q: 8 A-fragments (16 rows x 16 dims each), row-major ldm 128 ----
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> qf[8];
#pragma unroll
    for (int j = 0; j < 8; ++j)
        wmma::load_matrix_sync(qf[j], q + base + (long long)grow0 * HEAD_DIM + j * 16,
                               HEAD_DIM);

    // ---- O accumulators (8 head-dim halves of 16) ----
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc_o[8];
#pragma unroll
    for (int j = 0; j < 8; ++j) wmma::fill_fragment(acc_o[j], 0.0f);

    // Online softmax state in exp2 domain, per row (rows gid and gid+8).
    float m2[2] = {NEG_INF, NEG_INF}, l[2] = {0.f, 0.f};

    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
    if (grow0 >= seq_len) n_tiles = 0;

    for (int nt = 0; nt < n_tiles; ++nt) {
        // ---- stage K/V tile into shared (16B units, zero-pad rows >= S) ----
        {
            const int nchunk = BLOCK_N * HEAD_DIM / 8;
            const uint4 zero = make_uint4(0, 0, 0, 0);
            for (int i = threadIdx.x; i < nchunk; i += NUM_THREADS) {
                const int r = i / 16, u = i % 16;
                const int grow_kv = nt * BLOCK_N + r;
                if (grow_kv < seq_len) {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(
                            k + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) =
                        *reinterpret_cast<const uint4*>(
                            v + base_kv + (long long)grow_kv * HEAD_DIM + u * 8);
                } else {
                    *reinterpret_cast<uint4*>(&sK[r][u * 8]) = zero;
                    *reinterpret_cast<uint4*>(&sV[r][u * 8]) = zero;
                }
            }
        }
        __syncthreads();

        // ---- QK: 4 S accumulators (16 rows x 64 cols of this tile) ----
        wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> kf[4];
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_acc[4];
#pragma unroll
        for (int g = 0; g < 4; ++g) {
            wmma::load_matrix_sync(kf[g], &sK[g * 16][0], HEAD_DIM);
            wmma::fill_fragment(s_acc[g], 0.0f);
        }
#pragma unroll
        for (int g = 0; g < 4; ++g)
#pragma unroll
            for (int j = 0; j < 8; ++j)
                wmma::mma_sync(s_acc[g], qf[j], kf[g], s_acc[g]);

        // ---- per-lane online softmax (exp2 domain) + O rescale ----
        // element e of s_acc[g]: row = gid + 8*((e%4)/2), local col = 2*tig + 8*(e/4)
        float mt[2] = {NEG_INF, NEG_INF};
#pragma unroll
        for (int g = 0; g < 4; ++g)
#pragma unroll
            for (int e = 0; e < 8; ++e)
                mt[(e % 4) / 2] = fmaxf(mt[(e % 4) / 2], s_acc[g].x[e] * scale_log2);
#pragma unroll
        for (int off = 2; off > 0; off >>= 1) {  // reduce over the 4 tig lanes
            mt[0] = fmaxf(mt[0], __shfl_xor_sync(0xffffffffu, mt[0], off));
            mt[1] = fmaxf(mt[1], __shfl_xor_sync(0xffffffffu, mt[1], off));
        }
#pragma unroll
        for (int r = 0; r < 2; ++r) {
            const float m_new = fmaxf(m2[r], mt[r]);
            const float corr = __exp2f(m2[r] - m_new);
            l[r] *= corr;
            m2[r] = m_new;
#pragma unroll
            for (int j = 0; j < 8; ++j)
#pragma unroll
                for (int e = 0; e < 8; ++e)
                    if ((e % 4) / 2 == r) acc_o[j].x[e] *= corr;
        }

        // ---- PV: P fragments from softmaxed S; 8 V^T halves ----
        wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> vf[8];
#pragma unroll
        for (int j = 0; j < 8; ++j)
            wmma::load_matrix_sync(vf[j], &sV[0][j * 16], HEAD_DIM);

#pragma unroll
        for (int g = 0; g < 4; ++g) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> pf;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                const int row = grow0 + gid + 8 * ((e % 4) / 2);
                const int col = nt * BLOCK_N + 16 * g + 2 * tig + 8 * (e / 4);
                const bool valid = (col < seq_len) && (!causal || col <= row);
                const float s = s_acc[g].x[e] * scale_log2;
                const float p = valid ? __exp2f(s - m2[(e % 4) / 2]) : 0.f;
                pf.x[e] = __float2bfloat16(p);
                l[(e % 4) / 2] += p;
            }
#pragma unroll
            for (int j = 0; j < 8; ++j)
                wmma::mma_sync(acc_o[j], pf, vf[j], acc_o[j]);
        }
        __syncthreads();  // all warps done reading sK/sV before next tile load
    }

    // ---- epilogue: scale O by 1/l, stage through sK (reused as sO), write ----
    __syncthreads();
    float inv_l[2];
#pragma unroll
    for (int r = 0; r < 2; ++r) inv_l[r] = (l[r] > 0.f) ? 1.f / l[r] : 0.f;
    __nv_bfloat16 (*sO)[HEAD_DIM] = reinterpret_cast<__nv_bfloat16(*)[HEAD_DIM]>(sK);
#pragma unroll
    for (int j = 0; j < 8; ++j) {
#pragma unroll
        for (int e = 0; e < 8; ++e)
            acc_o[j].x[e] *= inv_l[(e % 4) / 2];
        wmma::store_matrix_sync(&sO[0][j * 16], acc_o[j], HEAD_DIM, wmma::mem_row_major);
    }
    __syncthreads();
    for (int idx = threadIdx.x; idx < BLOCK_M * HEAD_DIM; idx += NUM_THREADS) {
        const int row = idx / HEAD_DIM, col = idx % HEAD_DIM;
        const int grow = m_tile * BLOCK_M + row;
        if (grow < seq_len)
            out[base + (long long)grow * HEAD_DIM + col] = sO[row][col];
    }
}

