torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
                                torch::Tensor v, bool causal)
{
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "q/k/v must be CUDA tensors");
    TORCH_CHECK(q.scalar_type() == torch::kBFloat16 &&
                k.scalar_type() == torch::kBFloat16 &&
                v.scalar_type() == torch::kBFloat16, "q/k/v must be bfloat16");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "expected [B,H,S,D]");
    TORCH_CHECK(q.size(0) == k.size(0) && q.size(0) == v.size(0), "batch mismatch");
    TORCH_CHECK(q.size(2) == k.size(2) && q.size(2) == v.size(2), "seqlen mismatch");
    TORCH_CHECK(q.size(3) == HEAD_DIM && k.size(3) == HEAD_DIM && v.size(3) == HEAD_DIM,
                "head_dim must be ", HEAD_DIM);
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(),
                "q/k/v must be contiguous");

    const int B = q.size(0), H = q.size(1), kv_heads = k.size(1), S = q.size(2);
    TORCH_CHECK(H % kv_heads == 0, "H must be a multiple of kv_heads");
    TORCH_CHECK((long long)B * H <= 65535, "B*H exceeds grid.y limit");

    const at::cuda::CUDAGuard guard(q.device());
    auto out = torch::empty_like(q);
    if (S == 0) return out;

    const float scale_log2 = (1.0f / sqrtf((float)HEAD_DIM)) * LOG2E;
    dim3 grid((S + BLOCK_M - 1) / BLOCK_M, B * H);

    attention_fwd_kernel<<<grid, NUM_THREADS, 0,
                           at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()),
        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
        reinterpret_cast<__nv_bfloat16*>(out.data_ptr()),
        S, scale_log2, causal, H / kv_heads);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

